const saveOptions=()=>{const e=document.getElementById("enable-logging").checked,n=document.getElementById("hide-trending").checked,t=document.getElementById("hide-porn").checked;chrome.storage.sync.set({loggingEnabled:e,shouldHideTrending:n,shouldHidePorn:t},(()=>{const e=document.getElementById("status");e.textContent="The change has been saved.",setTimeout((()=>{e.textContent=""}),750)}))},restoreOptions=()=>{chrome.storage.sync.get({loggingEnabled:!0,shouldHideTrending:!0,shouldHidePorn:!1},(e=>{document.getElementById("enable-logging").checked=e.loggingEnabled,document.getElementById("hide-trending").checked=e.shouldHideTrending,document.getElementById("hide-porn").checked=e.shouldHidePorn}))};document.addEventListener("DOMContentLoaded",restoreOptions),document.getElementById("save").addEventListener("click",saveOptions);